/**
 * grapesjs und grapesjs-mjml liefern ihre Sprachdateien ohne Typen aus.
 */
declare module 'grapesjs-mjml/locale/de' {
    const messages: Record<string, unknown>;
    export default messages;
}

declare module 'grapesjs/locale/de' {
    const messages: Record<string, unknown>;
    export default messages;
}
